style.css:
@-moz-document domain("pinterest.com") {
body {
    background: linear-gradient(to bottom, red, black) !important;
    background-attachment: fixed !important;
  }

  /* Optional: Make the main feed pins stand out more */
  div[data-test-id="pin"] {
    background: white !important;
    border-radius: 8px !important;
    padding: 10px !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3) !important;
  }

  /* Optional: Make background areas transparent for contrast */
  div[data-test-id="simple-board-grid"] {
    background-color: transparent !important;
  }

  /* Remove other solid color backgrounds that might conflict */
  header,
  nav,
  footer,
  .NuxOverlay,
  .AppContent,
  .App {
    background-color: transparent !important;
  }
}
